package com.example.english_app;
import android.os.Bundle;import android.widget.EditText;import android.widget.Toast;public class WritingRevisionActivity extends LearningBaseActivity {@Override protected int layout(){return R.layout.activity_writing_revision;}@Override public void onCreate(Bundle b){super.onCreate(b);findViewById(R.id.send).setOnClickListener(v->{String s=((EditText)findViewById(R.id.revision)).getText().toString().trim();if(s.split("\\s+").length<3){message(R.id.error,"Vui lòng viết câu hoàn chỉnh (ít nhất 3 từ).");return;}Toast.makeText(this,"Đã nhập bản sửa. Chưa gửi.",Toast.LENGTH_SHORT).show();});findViewById(R.id.finishStepTwo).setOnClickListener(v->finishStepTwo());}}
